// docs/inference-chain.svg is generated by scripts/gen-inference-chain.ts. This regenerates it into a
// temp file and fails when the committed figure differs, so an edit to the module tables cannot leave
// the figure stale. A difference means: run `bun scripts/gen-inference-chain.ts` and commit the result.
import { expect, test } from "bun:test";
import { mkdtempSync, readFileSync, rmSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { DEFAULT_OUT } from "./gen-inference-chain";

const SCRIPT = join(import.meta.dir, "gen-inference-chain.ts");

test("the committed inference-chain figure equals what the generator emits", async () => {
  const dir = mkdtempSync(join(tmpdir(), "gen-inference-chain-"));
  try {
    const out = join(dir, "inference-chain.svg");
    const child = Bun.spawn([process.execPath, SCRIPT, "--out", out], { stdout: "pipe", stderr: "pipe" });
    const [stderr, code] = await Promise.all([new Response(child.stderr).text(), child.exited]);
    expect({ code, stderr }).toEqual({ code: 0, stderr: "" });
    expect(readFileSync(out, "utf8") === readFileSync(DEFAULT_OUT, "utf8")).toBe(true);
  } finally {
    rmSync(dir, { recursive: true, force: true });
  }
});
